import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as i,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"MiniMax Code 教程","description":"桌面端从下载页安装；CLI 官方命令是 mcode。两条通道都只抄官方原文。","frontmatter":{"title":"MiniMax Code 教程","description":"桌面端从下载页安装；CLI 官方命令是 mcode。两条通道都只抄官方原文。","domain":"product","tags":["coding-agent"],"role":"tutorial"},"headers":[],"relativePath":"zh/products/minimax-code/minimax-code.md","filePath":"zh/products/minimax-code/minimax-code.md","lastUpdated":1787110548000}'),o={name:"zh/products/minimax-code/minimax-code.md"};function d(l,a,n,r,c,h){return i(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="minimax-code-教程" tabindex="-1">MiniMax Code 教程 <a class="header-anchor" href="#minimax-code-教程" aria-label="Permalink to &quot;MiniMax Code 教程&quot;">​</a></h1><blockquote><p>本页带你从安装走到第一次对着本地仓库干活。参数清单见 <a href="./minimax-code-cheatsheet.html">速查表</a>，场景配方见 <a href="./minimax-code-cookbook.html">Cookbook</a>，名字辨析见 <a href="./minimax-code-glossary.html">术语表</a>。</p><p>MiniMax Code 有桌面端和 CLI 两张脸。官方原文：「它与桌面客户端互为补充」（<a href="https://agent.minimaxi.com/docs/cli/features" target="_blank" rel="noreferrer">CLI 功能介绍</a>）。先选一张脸装完，再学另一张。</p></blockquote><h2 id="_1-先选哪张脸" tabindex="-1">1. 先选哪张脸 <a class="header-anchor" href="#_1-先选哪张脸" aria-label="Permalink to &quot;1. 先选哪张脸&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你在哪干活</th><th>装什么</th><th>官方入口</th></tr></thead><tbody><tr><td>要窗口、浏览器预览、定时任务、手机遥控</td><td>桌面端</td><td><a href="https://agent.minimaxi.com/download" target="_blank" rel="noreferrer">国内下载</a> / <a href="https://agent.minimax.io/download" target="_blank" rel="noreferrer">海外下载</a></td></tr><tr><td>要终端、脚本、CI、编辑器 ACP</td><td>CLI（<code>mcode</code>）</td><td><a href="https://agent.minimaxi.com/docs/cli/quick-start" target="_blank" rel="noreferrer">CLI 快速开始</a></td></tr></tbody></table><p>两张都可以装。它们不是两个产品。</p><h2 id="_2-安装桌面端" tabindex="-1">2. 安装桌面端 <a class="header-anchor" href="#_2-安装桌面端" aria-label="Permalink to &quot;2. 安装桌面端&quot;">​</a></h2><p>原文来自 <a href="https://agent.minimaxi.com/docs/code/get-started/download" target="_blank" rel="noreferrer">下载与安装</a>：</p><blockquote><p>MiniMax Code 支持 macOS 和 Windows。安装完成后，使用 MiniMax 账号登录即可开始创建任务。</p></blockquote><table tabindex="0"><thead><tr><th>平台</th><th>要求</th></tr></thead><tbody><tr><td>macOS</td><td>macOS 11 Big Sur 及以上</td></tr><tr><td>Windows</td><td>Windows 10 及以上</td></tr></tbody></table><p>官方步骤（同一页）：</p><ol><li>打开下载页，选择与设备匹配的安装包。<strong>Apple 芯片 Mac 选 arm64，Intel Mac 选 x64。</strong></li><li>macOS 打开 <code>.dmg</code> 并拖入 Applications；Windows 运行安装程序并按提示完成。</li><li>启动 MiniMax Code，使用 MiniMax 账号登录。</li><li>后续有新版本时应用会提示更新；也可以在设置中手动检查。</li></ol><p>国内版：<a href="https://agent.minimaxi.com/download" target="_blank" rel="noreferrer">agent.minimaxi.com/download</a>。海外版：<a href="https://agent.minimax.io/download" target="_blank" rel="noreferrer">agent.minimax.io/download</a>。</p><p>官方 Note：「如果 Windows 安装或启动遇到问题，请先确认系统版本、安装路径权限和企业网络代理设置。」</p><p>桌面端<strong>没有</strong>官方一键 <code>curl</code> 安装命令。不要把下一节的 CLI 脚本拿来装桌面应用。</p><h2 id="_3-安装-cli" tabindex="-1">3. 安装 CLI <a class="header-anchor" href="#_3-安装-cli" aria-label="Permalink to &quot;3. 安装 CLI&quot;">​</a></h2><p>原文来自 <a href="https://agent.minimaxi.com/docs/cli/quick-start" target="_blank" rel="noreferrer">CLI 快速开始</a>：</p><blockquote><p>安装器会优先复用兼容的 Node.js；本机没有兼容版本时，会在用户目录中安装独立运行时。整个过程不需要 <code>sudo</code> 或管理员权限。</p></blockquote><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-6nBXZ" id="tab--kRJUSr" checked><label data-title="macOS / Linux / WSL" for="tab--kRJUSr">macOS / Linux / WSL</label><input type="radio" name="group-6nBXZ" id="tab-weEW0F_"><label data-title="Windows PowerShell" for="tab-weEW0F_">Windows PowerShell</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://filecdn.minimax.chat/public/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">filecdn.minimax.chat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div></div></div><p>安装完成后，重新打开终端：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>官方范围：macOS、Windows、常见 Linux 发行版和 WSL。<strong>暂不支持 Alpine / musl Linux。</strong></p><p>找不到命令时：先关终端再开，再跑 <code>mcode --version</code>。Windows 上已经打开的 VS Code 可能保留旧 <code>PATH</code>，需要完整退出 VS Code，而不是只新建终端标签（<a href="https://agent.minimaxi.com/docs/cli/faq" target="_blank" rel="noreferrer">CLI FAQ</a>）。</p><p>更新：<code>mcode update</code>，或在 TUI 里 <code>/update</code>。</p><h2 id="_4-登录" tabindex="-1">4. 登录 <a class="header-anchor" href="#_4-登录" aria-label="Permalink to &quot;4. 登录&quot;">​</a></h2><h3 id="桌面端" tabindex="-1">桌面端 <a class="header-anchor" href="#桌面端" aria-label="Permalink to &quot;桌面端&quot;">​</a></h3><p>启动后用 MiniMax 账号登录（<a href="https://agent.minimaxi.com/docs/code/get-started/download" target="_blank" rel="noreferrer">下载与安装</a>）。自备 Key 走设置里的 MiniMax API，见 <a href="./minimax-code-cookbook.html">Cookbook</a>。</p><h3 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h3><p>使用官方模型或 Token Plan 前先登录（<a href="https://agent.minimaxi.com/docs/cli/quick-start" target="_blank" rel="noreferrer">quick-start</a>）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span></code></pre></div><p>Global 账号：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --region</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> global</span></span></code></pre></div><p>登录在浏览器中完成。回到终端后，在 TUI 里跑 <code>/status</code> 检查账号、模型与运行状态。自定义 Provider 或 API Key 用 <code>mcode provider</code>。</p><p>中国大陆账号跑 <code>mcode login</code>，Global 账号跑 <code>mcode login --region global</code>（<a href="https://agent.minimaxi.com/docs/cli/faq" target="_blank" rel="noreferrer">CLI FAQ</a>）。登出：<code>mcode logout</code>。</p><p>WSL / SSH 回调步骤只抄 <a href="https://agent.minimaxi.com/docs/cli/faq" target="_blank" rel="noreferrer">CLI FAQ</a>，不要在本页展开。回调 URL 含临时凭证，不要发进聊天或仓库。</p><h2 id="_5-第一次任务-桌面端" tabindex="-1">5. 第一次任务：桌面端 <a class="header-anchor" href="#_5-第一次任务-桌面端" aria-label="Permalink to &quot;5. 第一次任务：桌面端&quot;">​</a></h2><p>来源：<a href="https://agent.minimaxi.com/docs/code/get-started/first-task" target="_blank" rel="noreferrer">创建第一个任务</a>。</p><ol><li>左侧导航点新建任务，或直接在首页输入框开始。</li><li>用自然语言说明要完成的事。官方举例：修复 bug、实现页面、整理报告、分析文件。</li><li>可以拖入文件、选择工作区、用 <code>@</code> 引用项目文件，或用 <code>/</code> 调用技能。</li><li>Agent 开始执行后继续补充要求；需要权限确认时再选。</li></ol><p>官方写任务的建议：</p><ul><li>说明目标结果，而不只是说明过程。</li><li>对代码任务，说明期望技术栈、限制条件和验收方式。</li><li>还不确定方案时，先让它进入规划讨论，再决定是否执行。</li></ul><p>需要改已有仓库时，先绑工作区。官方：「选择项目目录后，Agent 可以在该目录内读取文件、执行命令、生成产物并汇报变更。」只选与任务相关的目录（<a href="https://agent.minimaxi.com/docs/code/workflows/workspace" target="_blank" rel="noreferrer">工作区</a>）。</p><h2 id="_6-第一次任务-cli" tabindex="-1">6. 第一次任务：CLI <a class="header-anchor" href="#_6-第一次任务-cli" aria-label="Permalink to &quot;6. 第一次任务：CLI&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/your/project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span></span></code></pre></div><p>启动时直接提交：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;检查当前项目中失败的测试，修复后运行相关测试验证&quot;</span></span></code></pre></div><p>第一次进仓库可以先生成项目指导（官方会写或更新 <code>AGENTS.md</code>）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>官方建议任务里同时写期望结果、修改边界和验证方式（<a href="https://agent.minimaxi.com/docs/cli/quick-start" target="_blank" rel="noreferrer">quick-start</a>）。</p><p>继续上次：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --continue</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span></span></code></pre></div><p>TUI 内用 <code>/sessions [query]</code> 搜索和管理。已知 Session ID 时，<a href="https://agent.minimaxi.com/docs/cli/faq" target="_blank" rel="noreferrer">CLI FAQ</a> 写的是 <code>mcode --session</code> 加上该 ID。</p><p>入门键位（同一页）：</p><table tabindex="0"><thead><tr><th>操作</th><th>用途</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>发送；任务运行中再发会进等待队列</td></tr><tr><td><code>Shift+Enter</code></td><td>换行</td></tr><tr><td><code>@</code></td><td>引用工作区文件或目录</td></tr><tr><td><code>Shift+Tab</code></td><td>Default 与 Plan Mode 之间切换</td></tr><tr><td><code>Alt+M</code></td><td>Ask、Auto、Full access 之间切换</td></tr><tr><td><code>Esc</code></td><td>关面板，或中断正在跑的任务</td></tr></tbody></table><p>常用 slash：<code>/help</code>、<code>/status</code>、<code>/model</code>、<code>/sessions</code>、<code>/context</code>、<code>/compact</code>、<code>/new</code>、<code>/init</code>、<code>/quit</code>。完整集合以 TUI 里 <code>/help</code> 为准。</p><h2 id="_7-coding-模式还是-work-模式" tabindex="-1">7. Coding 模式还是 Work 模式 <a class="header-anchor" href="#_7-coding-模式还是-work-模式" aria-label="Permalink to &quot;7. Coding 模式还是 Work 模式&quot;">​</a></h2><p>只存在于<strong>桌面端</strong>。官方原文：「它们使用同一套 Agent 能力，但界面和工具暴露程度不同。」（<a href="https://agent.minimaxi.com/docs/code/workflows/modes" target="_blank" rel="noreferrer">Coding 与 Work 模式</a>）</p><table tabindex="0"><thead><tr><th>场景</th><th>推荐模式</th></tr></thead><tbody><tr><td>需要读取或修改代码仓库</td><td>Coding</td></tr><tr><td>需要打开终端、浏览器或文件面板</td><td>Coding</td></tr><tr><td>主要关注结果，不关心实现细节</td><td>Work</td></tr><tr><td>任务跨多个步骤但不涉及本地代码</td><td>Work</td></tr></tbody></table><p>Coding 适合：开发新功能、修 bug、跑测试和命令、审查 diff、调试网页或 HTML。Work 适合：文档、研究、表格、内容创作、日常办公自动化。</p><h2 id="_8-权限-先确认再改机器" tabindex="-1">8. 权限：先确认再改机器 <a class="header-anchor" href="#_8-权限-先确认再改机器" aria-label="Permalink to &quot;8. 权限：先确认再改机器&quot;">​</a></h2><p>桌面端（<a href="https://agent.minimaxi.com/docs/code/workflows/permissions" target="_blank" rel="noreferrer">权限与安全确认</a>）会在这些操作前确认：</p><ul><li>读取工作区外的文件</li><li>修改或删除文件</li><li>执行命令</li><li>使用可能产生外部影响的工具</li><li>处理远程控制或 IM 入口发来的操作</li></ul><p>官方建议：第一次用某个项目时保持较保守的授权；熟悉的低风险重复操作可以降低确认频率；对删除、覆盖、上传、发送消息保留人工确认。</p><p>CLI 里权限模式与 Plan Mode <strong>不是同一开关</strong>（<a href="https://agent.minimaxi.com/docs/cli/faq" target="_blank" rel="noreferrer">CLI FAQ</a>）：</p><ul><li>Plan Mode：下一条消息是直接执行还是先规划。<code>Shift+Tab</code> 或 <code>/plan</code>。</li><li>权限模式：工具操作如何确认。<code>Alt+M</code> 或 <code>/permission</code>，档位是 Ask、Auto、Full access。</li></ul><p><code>mcode exec</code> 可用 <code>--permission</code>，官方列出的值是 <code>ask</code>、<code>smart</code>、<code>full</code> 或 <code>off</code>（<a href="https://agent.minimaxi.com/docs/cli/features" target="_blank" rel="noreferrer">features</a>）。TUI 档名和 exec 档名不要混写成一张表的同一列。</p><h2 id="_9-接下来做什么" tabindex="-1">9. 接下来做什么 <a class="header-anchor" href="#_9-接下来做什么" aria-label="Permalink to &quot;9. 接下来做什么&quot;">​</a></h2><ul><li>复杂任务拆给多个 Agent：<a href="./minimax-code-cookbook.html">Cookbook · Agent Team</a></li><li>脚本 / CI：<code>mcode exec</code></li><li>编辑器：<code>mcode acp</code>（官方给了 Zed 配置）</li><li>回查命令：<a href="./minimax-code-cheatsheet.html">速查表</a></li></ul>`,66)])])}const u=e(o,[["render",d]]);export{b as __pageData,u as default};
